package paternsTUF;

public class Pattern2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Pattern2(5);
		

	}
	public static void Pattern2(int n) {
		for(int i=0;i<n;i++) {
			for(int j=0;j<=i;j++) {
				System.out.print("* ");
			}
			System.out.println();
		}
	}

}
